/* share.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "./context.js";

export function install(P) {


  /* ---------- shareable settings links ---------- */

  function encodeShareToken(payload) {
    const bytes = new TextEncoder().encode(JSON.stringify(payload));
    let binary = "";
    bytes.forEach((byte) => { binary += String.fromCharCode(byte); });
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function decodeShareToken(token) {
    const base64 = String(token).replace(/-/g, "+").replace(/_/g, "/");
    const binary = atob(base64 + "=".repeat((4 - base64.length % 4) % 4));
    const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
    return JSON.parse(new TextDecoder().decode(bytes));
  }

  function readSharedSettings() {
    try {
      const token = new URLSearchParams(window.location.search).get(P.SHARE_PARAM);
      if (!token) return null;
      const raw = P.decodeShareToken(token);
      if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
      const shared = {};
      P.SHARE_KEYS.forEach((key) => {
        if (Object.prototype.hasOwnProperty.call(raw, key)) shared[key] = raw[key];
      });
      if (Object.prototype.hasOwnProperty.call(shared, "engine")) {
        if (!P.ENGINES.includes(shared.engine)) delete shared.engine;
        else shared.engineExplicit = true; // a shared engine must beat auto-detection
      }
      if (Object.prototype.hasOwnProperty.call(shared, "format") && !P.FORMATS.includes(shared.format)) delete shared.format;
      return Object.keys(shared).length ? shared : null;
    } catch { return null; }
  }

  function clearShareParam() {
    try {
      const url = new URL(window.location.href);
      if (!url.searchParams.has(P.SHARE_PARAM)) return;
      url.searchParams.delete(P.SHARE_PARAM);
      window.history.replaceState(window.history.state, "", `${url.pathname}${url.search}${url.hash}`);
    } catch {}
  }

  function readTimeParam() {
    try {
      const raw = new URLSearchParams(window.location.search).get(P.TIME_PARAM);
      if (raw === null) return null;
      const value = Number(raw);
      return Number.isFinite(value) && value >= 0 ? value : null;
    } catch { return null; }
  }

  function buildShareUrl() {
    const payload = {};
    P.SHARE_KEYS.forEach((key) => { payload[key] = P.state[key]; });
    // Always point at the music page: it is the only page that can select the
    // album/track from the catalog before handing the timecode to the player.
    const url = P.SITE_ROOT ? new URL("music/", P.SITE_ROOT) : new URL(window.location.href);
    url.search = "";
    url.hash = "";
    const albumId = P.state.context?.albumId;
    if (albumId) url.searchParams.set("album", albumId);
    if (P.state.current && Number.isInteger(P.state.current.index)) {
      url.searchParams.set("track", String(P.state.current.index));
    }
    const time = P.state.current ? Math.round((P.audio.currentTime || P.state.time || 0) * 100) / 100 : 0;
    if (time > 0) url.searchParams.set(P.TIME_PARAM, String(time));
    url.searchParams.set(P.SHARE_PARAM, P.encodeShareToken(payload));
    if (albumId) url.hash = encodeURIComponent(albumId);
    return url.href;
  }

  function copyText(text) {
    if (navigator.clipboard?.writeText) return navigator.clipboard.writeText(text);
    return new Promise((resolve, reject) => {
      const input = document.createElement("textarea");
      input.value = text;
      input.setAttribute("readonly", "");
      input.style.position = "fixed";
      input.style.opacity = "0";
      document.body.appendChild(input);
      input.select();
      let copied = false;
      try { copied = document.execCommand("copy"); } catch {}
      input.remove();
      if (copied) resolve();
      else reject(new Error("copy failed"));
    });
  }

  function showShareStatus(button, message, url) {
    const field = button.closest(".share-setting");
    const status = field?.querySelector("[data-share-status]");
    const input = field?.querySelector("[data-share-url]");
    if (status) status.textContent = message;
    if (input) {
      input.hidden = !url;
      if (url) { input.value = url; input.focus(); input.select(); }
    }
    const previous = P.shareStatusTimers.get(button);
    if (previous) window.clearTimeout(previous);
    P.shareStatusTimers.set(button, window.setTimeout(() => {
      if (status) status.textContent = "";
      if (input) input.hidden = true;
      P.shareStatusTimers.delete(button);
    }, 4000));
  }

  function shareSettings(button) {
    let url;
    try { url = P.buildShareUrl(); } catch { return; }
    P.copyText(url)
      .then(() => P.showShareStatus(button, P.pt("shareCopied")))
      .catch(() => P.showShareStatus(button, P.pt("shareManual"), url));
  }
  Object.assign(P, { encodeShareToken, decodeShareToken, readSharedSettings, clearShareParam, readTimeParam, buildShareUrl, copyText, showShareStatus, shareSettings });
}
